<?php require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../services/authService.php';require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../includes/csrf.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('POST required');}requireValidCsrf();$user=authenticate(openDatabase(),(string)($_POST['email']??''),(string)($_POST['password']??''));if(!$user){header('Location: login.php?error=1',true,303);exit;}startSecureSession();session_regenerate_id(true);$_SESSION['user_id']=$user['user_id'];$_SESSION['email']=$user['email'];$_SESSION['display_name']=$user['display_name'];$_SESSION['roles']=$user['roles'];$_SESSION['last_activity']=time();header('Location: dashboard.php',true,303);exit;
